import { DocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) => {
	const doc = DocAccess.use(docQuery(props.id));
	return <h1>{doc.title}</h1>;
};

import { Match, Result } from "effect";

import { Session } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) =>
	Result.match(Session.useResult(docQuery(props.id)), {
		onFailure: (error) =>
			Match.valueTags(error, {
				DocNotFound: () => <p>No such doc</p>,
			}),
		onSuccess: (doc) => <h1>{doc.title}</h1>,
	});

import { Match, Result } from "effect";

import { DocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) =>
	Result.match(DocAccess.useResult(docQuery(props.id)), {
		onFailure: (error) =>
			Match.valueTags(error, {
				DocNotFound: () => <p>No such doc</p>,
				Unauthorized: () => <p>Sign in</p>,
			}),
		onSuccess: (doc) => <h1>{doc.title}</h1>,
	});

import { Unauthorized } from "../src/api.ts";
import { DocAccess } from "../src/boundaries.tsx";

export const Again = DocAccess.catchErrors({
	errors: [Unauthorized],
	fallback: () => <p>Sign in again</p>,
	name: "Again",
});

import { Context, Effect } from "effect";
import { Query } from "@raf-query/experimental-effect-query";

import { DocAccess } from "../src/boundaries.tsx";

class Analytics extends Context.Service<
	Analytics,
	{ readonly views: Effect.Effect<number> }
>()("Analytics") {}

const views = Query.make({
	effect: Effect.flatMap(Analytics, (analytics) => analytics.views),
	key: ["views"],
});

export const Views = () => <p>{DocAccess.use(views)} views</p>;

import { Result } from "effect";

import { DocNotFound } from "../src/api.ts";
import { DocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

const Everything = DocAccess.catchErrors({
	errors: [DocNotFound],
	fallback: (props) => <p>Doc {props.error.docId} is gone</p>,
	name: "Everything",
});

export const Title = (props: { readonly id: number }) => {
	const doc = Everything.use(docQuery(props.id));
	return <h1>{doc.title}</h1>;
};

export const Body = (props: { readonly id: number }) => {
	const result = Everything.useResult(docQuery(props.id));
	if (Result.isFailure(result)) {
		const impossible: never = result.failure;
		return impossible;
	}
	return <p>{result.success.body}</p>;
};
